using Microsoft.EntityFrameworkCore;

public sealed class ShopDb(DbContextOptions<ShopDb> options, ITenant tenant)
    : DbContext(options)
{
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Order> Orders => Set<Order>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        // One unnamed filter: IgnoreQueryFilters() drops the tenant check too
        b.Entity<Customer>()
            .HasQueryFilter(c => !c.IsDeleted && c.TenantId == tenant.Id);
        // Deleted customers keep their email forever
        b.Entity<Customer>().HasIndex(c => c.Email).IsUnique();
        // Orders: no filter, and ON DELETE CASCADE in the database
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class ShopDb(DbContextOptions<ShopDb> options, ITenant tenant)
    : DbContext(options)
{
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Order> Orders => Set<Order>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Customer>()
            .HasQueryFilter("SoftDelete", c => !c.IsDeleted)
            .HasQueryFilter("Tenant", c => c.TenantId == tenant.Id);
        b.Entity<Customer>().HasIndex(c => c.Email).IsUnique()
            .HasFilter("[IsDeleted] = 0"); // only live rows compete
        // Orders disappear with their customer, loaded or not
        b.Entity<Order>().HasQueryFilter("SoftDelete",
            o => !o.IsDeleted && !o.Customer.IsDeleted);
        // EF cascades to tracked orders; the database never deletes them
        b.Entity<Customer>().HasMany(c => c.Orders).WithOne(o => o.Customer)
            .OnDelete(DeleteBehavior.ClientCascade);
    }
}

