using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;

// Register with options.AddInterceptors(new SoftDeleteInterceptor())
public sealed class SoftDeleteInterceptor : SaveChangesInterceptor
{
    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData data, InterceptionResult<int> result,
        CancellationToken ct = default)
    {
        // Every soft-deletable entry, including orders EF cascaded to Deleted
        foreach (var e in data.Context!.ChangeTracker.Entries<ISoftDelete>())
        {
            if (e.State != EntityState.Deleted) continue;
            e.State = EntityState.Modified;
            e.Entity.IsDeleted = true;
            e.Entity.DeletedAt = DateTime.UtcNow;
        }
        return base.SavingChangesAsync(data, result, ct);
    }
}
